INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('typing', '{"text": "Cybersecurity has become an important concern for businesses of every size. Many companies now require employees to use strong passwords and change them regularly to reduce the risk of unauthorized access to sensitive information. Phishing emails, which attempt to trick employees into revealing personal information, remain one of the most common methods used by cybercriminals. For this reason, many organizations provide regular training sessions to help employees recognize suspicious messages and avoid clicking on unknown links. Keeping software updated is another simple but effective way to protect company systems from known vulnerabilities. Investing time and resources into cybersecurity awareness can prevent costly data breaches and protect a company''s reputation among its clients and partners in the long run."}'::jsonb, '{"exact": "Cybersecurity has become an important concern for businesses of every size. Many companies now require employees to use strong passwords and change them regularly to reduce the risk of unauthorized access to sensitive information. Phishing emails, which attempt to trick employees into revealing personal information, remain one of the most common methods used by cybercriminals. For this reason, many organizations provide regular training sessions to help employees recognize suspicious messages and avoid clicking on unknown links. Keeping software updated is another simple but effective way to protect company systems from known vulnerabilities. Investing time and resources into cybersecurity awareness can prevent costly data breaches and protect a company''s reputation among its clients and partners in the long run."}'::jsonb, 122, 0.52, 'B2', 'approved', 'exam', 'technology', 'c3000000-0000-4000-8000-000000000011', 1);
