INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Felix noticed the company website had suddenly stopped loading. He quickly checked the server logs and found a configuration error. After correcting the setting, the website came back online within minutes. Felix documented the issue to prevent it from happening again."}'::jsonb, '{"key_points": ["Felix noticed the website stopped loading", "he found a configuration error in the logs", "he fixed it and the site came back online", "he documented the issue"]}'::jsonb, 41, 0.52, 'B1', 'approved', 'exam', 'technology', 'c3000000-0000-4000-8000-000000000014', 1),
('passage_reconstruction', '{"passage": "Amara discovered a security flaw while testing new software. She reported it immediately instead of ignoring it. The development team fixed the flaw within a day. Amara received recognition for catching the issue before launch."}'::jsonb, '{"key_points": ["Amara discovered a security flaw while testing", "she reported it immediately", "the team fixed it within a day", "she was recognized for catching it before launch"]}'::jsonb, 35, 0.55, 'B2', 'approved', 'exam', 'technology', 'c3000000-0000-4000-8000-000000000014', 2),
('passage_reconstruction', '{"passage": "Thank you for reporting the login issue you experienced yesterday. Our technical team has identified the cause and deployed a fix. Please try logging in again, and let us know if the problem continues."}'::jsonb, '{"key_points": ["thanks for reporting the login issue", "the cause was identified and a fix deployed", "asks them to try logging in again"]}'::jsonb, 33, 0.53, 'B1', 'approved', 'exam', 'technology', 'c3000000-0000-4000-8000-000000000014', 3),
('passage_reconstruction', '{"passage": "I wanted to let you know that the scheduled maintenance has been moved to this weekend instead of tonight. The system will be briefly unavailable on Saturday between midnight and 2 a.m. We apologize for any inconvenience."}'::jsonb, '{"key_points": ["maintenance moved to the weekend", "system unavailable Saturday midnight to 2am", "apologizes for the inconvenience"]}'::jsonb, 37, 0.55, 'B2', 'approved', 'exam', 'technology', 'c3000000-0000-4000-8000-000000000014', 4);
INSERT INTO items (item_type_id, content, answer_set, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('email_writing', '{"prompt": "You work in IT support. Your manager, Mr. Diaz, wants to reduce the number of repeated support tickets. Write an email to him suggesting three ways to achieve this. Your suggestions must come from the following three themes: better documentation, employee training sessions, an internal FAQ page. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.55, 'B2', 'approved', 'exam', 'technology', 'c3000000-0000-4000-8000-000000000015', 1),
('email_writing', '{"prompt": "You work at a software company. A client, Ms. Rivera, reported that a recent update caused her software to crash frequently. Write an email to her apologizing and explaining the next steps. Your response must address the following three themes: an apology for the disruption, an explanation of the fix timeline, an offer of temporary support. You should include all three themes with a clear, professional tone."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'technology', 'c3000000-0000-4000-8000-000000000015', 2);
